@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;0,900;1,400;1,700&family=Inter:wght@300;400;500;600&display=swap');

/* ========== Reset & Base ========== */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --bg: #F5F2ED;
  --bg-dark: #EDE9E3;
  --text: #1A1A1A;
  --text-light: #5A5550;
  --accent-terracotta: #C4705A;
  --accent-sage: #8B9E7E;
  --accent-sand: #C8B898;
  --accent-warm: #B8856C;
  --serif: 'Playfair Display', 'Georgia', serif;
  --sans: 'Inter', -apple-system, 'Helvetica Neue', sans-serif;
  --max-width: 1400px;
  --reading-width: 680px;
  --gutter: clamp(1.5rem, 5vw, 6rem);
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--sans);
  font-weight: 400;
  line-height: 1.7;
  color: var(--text);
  background-color: var(--bg);
}

a {
  color: var(--text);
  text-decoration: none;
  transition: opacity 0.25s ease;
}

a:hover {
  opacity: 0.6;
}

img {
  max-width: 100%;
  display: block;
}

/* ========== Typography ========== */
h1, h2, h3 {
  font-family: var(--serif);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.01em;
}

h1 {
  font-size: clamp(2.8rem, 7vw, 6.5rem);
}

h2 {
  font-size: clamp(2rem, 4.5vw, 4rem);
}

h3 {
  font-size: clamp(1.3rem, 2vw, 1.75rem);
}

p {
  font-size: clamp(1rem, 1.1vw, 1.125rem);
  color: var(--text-light);
  max-width: 65ch;
}

.label {
  font-family: var(--sans);
  font-weight: 500;
  font-size: 0.8rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-light);
}

/* ========== Layout ========== */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding-left: var(--gutter);
  padding-right: var(--gutter);
}

.section {
  padding-top: clamp(4rem, 10vh, 8rem);
  padding-bottom: clamp(4rem, 10vh, 8rem);
}

/* ========== Header / Navigation ========== */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  padding: 1.5rem 0;
  background: var(--bg);
  transition: background 0.3s ease;
}

.header-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--gutter);
}

.logo {
  font-family: var(--serif);
  font-weight: 900;
  font-size: 1.5rem;
  letter-spacing: -0.02em;
}

.nav-desktop {
  display: flex;
  gap: 2.5rem;
  list-style: none;
}

.nav-desktop a {
  font-family: var(--sans);
  font-weight: 400;
  font-size: 0.95rem;
  letter-spacing: 0.01em;
}

.nav-desktop a.active {
  font-weight: 600;
}

/* Hamburger */
.hamburger {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  width: 32px;
  height: 24px;
  position: relative;
  z-index: 1100;
}

.hamburger span {
  display: block;
  width: 100%;
  height: 2px;
  background: var(--text);
  position: absolute;
  left: 0;
  transition: all 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}

.hamburger span:nth-child(1) { top: 0; }
.hamburger span:nth-child(2) { top: 11px; }
.hamburger span:nth-child(3) { top: 22px; }

.hamburger.open span:nth-child(1) {
  top: 11px;
  transform: rotate(45deg);
}

.hamburger.open span:nth-child(2) {
  opacity: 0;
}

.hamburger.open span:nth-child(3) {
  top: 11px;
  transform: rotate(-45deg);
}

/* Mobile Menu Overlay */
.mobile-menu {
  display: none;
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 1050;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 2.5rem;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.4s ease, visibility 0.4s ease;
}

.mobile-menu.open {
  opacity: 1;
  visibility: visible;
}

.mobile-menu a {
  font-family: var(--serif);
  font-size: clamp(2rem, 8vw, 4rem);
  font-weight: 700;
}

/* ========== Hero ========== */
.hero {
  padding-top: clamp(8rem, 18vh, 14rem);
  padding-bottom: clamp(3rem, 6vh, 5rem);
}

.hero h1 {
  max-width: 14ch;
}

/* ========== Media Showcase ========== */
.media-showcase {
  padding-bottom: clamp(4rem, 8vh, 7rem);
}

.media-grid {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr 1fr;
  gap: 1.25rem;
  height: clamp(280px, 45vw, 550px);
}

.media-block {
  border-radius: 6px;
  position: relative;
  overflow: hidden;
}

.media-block:nth-child(1) { background: var(--accent-terracotta); }
.media-block:nth-child(2) { background: var(--accent-sage); }
.media-block:nth-child(3) { background: var(--accent-sand); }

/* ========== Client Marquee ========== */
.client-marquee {
  padding: clamp(3rem, 6vh, 5rem) 0;
  overflow: hidden;
}

.marquee-row {
  display: flex;
  white-space: nowrap;
  margin-bottom: 1rem;
}

.marquee-track {
  display: flex;
  align-items: center;
  gap: 0;
  will-change: transform;
}

.marquee-row:nth-child(odd) .marquee-track {
  animation: marquee-left 30s linear infinite;
}

.marquee-row:nth-child(even) .marquee-track {
  animation: marquee-right 30s linear infinite;
}

@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

.marquee-item {
  font-family: var(--serif);
  font-weight: 700;
  font-size: clamp(1.8rem, 4vw, 3.5rem);
  padding: 0 1.5rem;
  flex-shrink: 0;
}

.marquee-separator {
  color: var(--accent-warm);
  font-size: clamp(0.8rem, 1.5vw, 1.2rem);
  padding: 0 0.5rem;
  flex-shrink: 0;
  opacity: 0.5;
}

/* ========== About Section ========== */
.about {
  display: grid;
  grid-template-columns: 1fr 1.5fr;
  gap: clamp(2rem, 5vw, 6rem);
  align-items: start;
}

.about p {
  margin-bottom: 1.5rem;
}

.about p:last-child {
  margin-bottom: 0;
}

/* ========== Founder Letter (Neweno) ========== */
.founder-letter {
  padding-top: clamp(8rem, 18vh, 14rem);
  padding-bottom: clamp(4rem, 10vh, 8rem);
  max-width: var(--reading-width);
  margin: 0 auto;
}

.founder-letter h1 {
  margin-bottom: clamp(3rem, 6vh, 5rem);
  font-size: clamp(2.5rem, 6vw, 5rem);
}

.founder-letter p {
  font-size: clamp(1.05rem, 1.2vw, 1.2rem);
  line-height: 1.85;
  color: var(--text);
  margin-bottom: 1.8rem;
  max-width: none;
}

.founder-letter .signoff {
  margin-top: clamp(2rem, 4vh, 3rem);
  font-family: var(--serif);
  font-style: italic;
  font-size: 1.2rem;
  color: var(--text);
}

/* ========== Services Page ========== */
.philosophy {
  padding-top: clamp(8rem, 18vh, 14rem);
  padding-bottom: clamp(3rem, 6vh, 5rem);
}

.philosophy h1 {
  font-size: clamp(2.5rem, 6vw, 5rem);
  max-width: 16ch;
  margin-bottom: clamp(2rem, 4vh, 3rem);
}

.philosophy-text {
  max-width: var(--reading-width);
}

.philosophy-text p {
  font-size: clamp(1.05rem, 1.2vw, 1.15rem);
  line-height: 1.85;
  margin-bottom: 1.5rem;
  color: var(--text);
}

.divider {
  border: none;
  border-top: 1px solid rgba(26, 26, 26, 0.12);
  margin: clamp(3rem, 6vh, 5rem) 0;
}

.services-section {
  padding-bottom: clamp(4rem, 10vh, 8rem);
}

.services-question {
  font-family: var(--serif);
  font-size: clamp(1.6rem, 3vw, 2.5rem);
  font-weight: 700;
  font-style: italic;
  margin-bottom: clamp(3rem, 6vh, 5rem);
  max-width: 20ch;
}

.service-item {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: clamp(2rem, 4vw, 4rem);
  padding: clamp(2rem, 4vh, 3rem) 0;
  border-top: 1px solid rgba(26, 26, 26, 0.12);
}

.service-item:last-child {
  border-bottom: 1px solid rgba(26, 26, 26, 0.12);
}

.service-name {
  font-family: var(--serif);
  font-weight: 700;
  font-size: 1.5rem;
}

.service-description {
  font-size: clamp(1rem, 1.1vw, 1.1rem);
  line-height: 1.85;
  color: var(--text-light);
  max-width: 60ch;
}

/* ========== Clients Grid ========== */
.clients-heading {
  padding-top: clamp(8rem, 18vh, 14rem);
  padding-bottom: clamp(2rem, 4vh, 3rem);
}

.clients-heading h1 {
  font-size: clamp(2.5rem, 6vw, 5rem);
}

.clients-heading .subtitle {
  font-family: var(--sans);
  font-size: 1rem;
  color: var(--text-light);
  margin-top: 0.75rem;
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(1.5rem, 3vw, 2.5rem);
  padding-bottom: clamp(4rem, 10vh, 8rem);
}

.client-card {
  padding: clamp(1.5rem, 2vw, 2rem) 0;
  border-top: 1px solid rgba(26, 26, 26, 0.12);
}

.client-card h3 {
  font-family: var(--serif);
  font-weight: 700;
  font-size: clamp(1.15rem, 1.5vw, 1.4rem);
  margin-bottom: 0.75rem;
}

.client-card p {
  font-size: 0.95rem;
  line-height: 1.7;
  color: var(--text-light);
}

/* ========== Contact Page ========== */
.contact-hero {
  padding-top: clamp(10rem, 25vh, 20rem);
  padding-bottom: clamp(2rem, 4vh, 3rem);
  text-align: center;
}

.contact-hero h1 {
  font-size: clamp(4rem, 15vw, 14rem);
  line-height: 1;
  letter-spacing: -0.03em;
}

.contact-links {
  text-align: center;
  padding-bottom: clamp(6rem, 15vh, 12rem);
}

.contact-links-list {
  list-style: none;
  display: flex;
  justify-content: center;
  gap: clamp(2rem, 4vw, 4rem);
  margin-top: clamp(2rem, 4vh, 3rem);
}

.contact-links-list a {
  font-family: var(--sans);
  font-size: clamp(1rem, 1.3vw, 1.2rem);
  font-weight: 400;
  border-bottom: 1px solid rgba(26, 26, 26, 0.2);
  padding-bottom: 0.25rem;
  transition: border-color 0.3s ease, opacity 0.25s ease;
}

.contact-links-list a:hover {
  border-color: var(--text);
  opacity: 1;
}

/* ========== Footer ========== */
.footer {
  padding: 3rem 0;
  border-top: 1px solid rgba(26, 26, 26, 0.08);
}

.footer-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer-text {
  font-size: 0.85rem;
  color: var(--text-light);
}

/* ========== Responsive ========== */
@media (max-width: 900px) {
  .nav-desktop {
    display: none;
  }

  .hamburger {
    display: block;
  }

  .mobile-menu {
    display: flex;
  }

  .about {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }

  .media-grid {
    grid-template-columns: 1fr 1fr;
    height: auto;
  }

  .media-block {
    min-height: 200px;
  }

  .media-block:nth-child(3) {
    grid-column: 1 / -1;
    min-height: 180px;
  }

  .service-item {
    grid-template-columns: 1fr;
    gap: 0.75rem;
  }

  .clients-grid {
    grid-template-columns: 1fr 1fr;
  }

  .contact-links-list {
    flex-direction: column;
    align-items: center;
    gap: 1.5rem;
  }

  .footer-inner {
    flex-direction: column;
    gap: 1rem;
    text-align: center;
  }
}

@media (max-width: 600px) {
  .media-grid {
    grid-template-columns: 1fr;
  }

  .media-block:nth-child(3) {
    grid-column: auto;
  }

  .clients-grid {
    grid-template-columns: 1fr;
  }
}

